html.script:
(blockcontext, pageContext, item) => {
    let message = item.message;
    let eventType = item.eventType;

    if (eventType === "INCIDENT_ACCEPTED_AS_MAJOR_INCIDENT") {
        return '<div style="border: 0.0625rem solid #F8C8CD; background: #F8C8CD; color: #000000; border-radius: 0.25rem; padding: 0.25rem 0.5rem 0.25rem 0.5rem;">' + message + '</div>';
    } else if (eventType === "INCIDENT_RESOLVED") {
        return '<div style="border: 0.0625rem solid #D4EED8; background: #D4EED8; color: #000000; border-radius: 0.25rem; padding: 0.25rem 0.5rem 0.25rem 0.5rem;">' + message + '</div>';
    }
    return '<div style="border: 0.0625rem solid #F6F6F8; background: #EDEEF8; color: #000000; border-radius: 0.25rem; padding: 0.25rem 0.5rem 0.25rem 0.5rem;">' + message + '</div>';
}
